// Global API directory (generated by scripts/import-openapi.js from the APIs.guru
// OpenAPI Directory). The index is small and loaded at start-up; each API's
// operations are loaded from disk the first time that API is used.

import { readFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { makeHandler } from "./connector.js";

const DIR = fileURLToPath(new URL("../catalog/openapi/", import.meta.url));

export const DIRECTORY_CATEGORIES = [
  { slug: "open-data", displayName: "Open Data", color: "#38bdf8", description: "Government and public datasets from around the world." },
  { slug: "analytics", displayName: "Analytics", color: "#a78bfa", description: "Analytics, measurement and reporting APIs." },
  { slug: "communication", displayName: "Communication", color: "#22d3ee", description: "SMS, voice, email and messaging." },
  { slug: "ecommerce", displayName: "E-commerce", color: "#f472b6", description: "Stores, catalogs, orders and shipping." },
  { slug: "payments", displayName: "Payments", color: "#34d399", description: "Payment processing and invoicing." },
  { slug: "entertainment", displayName: "Entertainment", color: "#fb923c", description: "Sports, games and entertainment data." },
  { slug: "media", displayName: "Media", color: "#e879f9", description: "Images, video, audio and publishing." },
  { slug: "transport", displayName: "Transport", color: "#facc15", description: "Travel, flights, transit and mobility." },
  { slug: "business", displayName: "Business", color: "#60a5fa", description: "CRM, marketing, collaboration and productivity." },
  { slug: "cloud", displayName: "Cloud", color: "#94a3b8", description: "Hosting, storage and infrastructure services." },
  { slug: "security", displayName: "Security", color: "#f87171", description: "Identity, security and fraud prevention." },
  { slug: "iot", displayName: "IoT", color: "#4ade80", description: "Devices, sensors and smart home." },
  { slug: "education", displayName: "Education", color: "#fbbf24", description: "Learning and education data." },
];

let cache = null;
export function loadDirectoryIndex() {
  if (cache) return cache;
  const file = DIR + "index.json";
  cache = existsSync(file) ? JSON.parse(readFileSync(file, "utf8")).apis : [];
  return cache;
}

const T = { s: "string" };
/** Build Apizie endpoints for one directory API (called lazily). */
export function loadEndpoints(entry, buildEndpoint) {
  const raw = JSON.parse(readFileSync(`${DIR}apis/${entry.f}.json`, "utf8"));
  const api = { key: entry.k, name: entry.n, base: raw.base, auth: raw.auth };
  return raw.ops.map(([slug, method, path, summary, fields, body]) => {
    const fl = fields.map(([name, type, req, loc, extra = {}]) => ({
      name,
      type: T[type] ?? type,
      required: !!req,
      src: { p: "path", q: "query", h: "header" }[loc],
      ...(extra.x ? { description: extra.x } : {}),
      ...(extra.d !== undefined ? { default: extra.d } : {}),
      ...(extra.e ? { enum: extra.e } : {}),
      ...(extra.ex !== undefined ? { example: extra.ex } : {}),
    }));
    if (body && method !== "GET" && method !== "HEAD" && !fl.some((f) => f.name === "body")) fl.push({ name: "body", type: "object", required: body === 2 || body === 4, src: "body", description: body >= 3 ? "Form fields as a JSON object" : "JSON request body" });
    const op = { method, path, fields: fl, body };
    return buildEndpoint({
      slug,
      displayName: summary,
      description: `${method} ${path}`,
      method: method === "GET" ? "GET" : "POST",
      upstreamMethod: method,
      fields: fl,
      cacheTtl: method === "GET" ? 60 : 0,
      bulkEnabled: method === "GET",
      timeoutMs: 25000,
      handler: makeHandler(api, op),
      status: entry.a ? "byok" : "live",
    });
  });
}
